@pytest.fixture(autouse=True)
def local_only_network(monkeypatch):
    original_connect = socket.socket.connect
    original_connect_ex = socket.socket.connect_ex
    original_getaddrinfo = socket.getaddrinfo

    def ensure_loopback(address):
        if not isinstance(address, tuple):
            raise AssertionError("Non-IP network activity is forbidden in this corpus")
        try:
            loopback = ipaddress.ip_address(address[0]).is_loopback
        except ValueError:
            loopback = False
        if not loopback:
            raise AssertionError("External network activity is forbidden in this corpus")

    def guarded_connect(sock, address):
        ensure_loopback(address)
        return original_connect(sock, address)

    def guarded_connect_ex(sock, address):
        ensure_loopback(address)
        return original_connect_ex(sock, address)

    def guarded_getaddrinfo(host, *args, **kwargs):
        ensure_loopback((host, 0))
        return original_getaddrinfo(host, *args, **kwargs)

    monkeypatch.setattr(socket.socket, "connect", guarded_connect)
    monkeypatch.setattr(socket.socket, "connect_ex", guarded_connect_ex)
    monkeypatch.setattr(socket, "getaddrinfo", guarded_getaddrinfo)

